/**
 * Smart Compact Extension for Pi Coding Agent
 *
 * Uses a configurable model for session compaction instead of the default model.
 * The provider/model pair is read from ~/.pi/agent/custom/smart-compact/config.json generated by Nix config.
 * Falls back to default compaction if the configured model is unavailable.
 */

import { complete } from "@earendil-works/pi-ai/compat";
import type {
  ExtensionAPI,
  ExtensionContext,
} from "@earendil-works/pi-coding-agent";
import {
  convertToLlm,
  serializeConversation,
} from "@earendil-works/pi-coding-agent";
import * as os from "node:os";
import * as path from "node:path";
import { memoizeByStat } from "./lib/cache.js";

const configPath = path.join(
  os.homedir(),
  ".pi/agent/custom/smart-compact/config.json",
);

interface SmartCompactAutoConfig {
  enable?: boolean;
  maxContextTokens?: number;
  contextRatio?: number;
}

interface NormalizedAutoCompactConfig {
  maxContextTokens: number;
  contextRatio: number;
}

interface SmartCompactConfig {
  provider?: string;
  model?: string;
  maxTokens?: number;
  autoCompact?: SmartCompactAutoConfig;
  vcc?: { enable?: boolean };
}

const DEFAULT_AUTO_COMPACT_MAX_CONTEXT_TOKENS = 150_000;
const DEFAULT_AUTO_COMPACT_CONTEXT_RATIO = 0.8;

async function loadCompactionConfig(): Promise<SmartCompactConfig | null> {
  try {
    const parsed = await memoizeByStat(
      configPath,
      (content) => JSON.parse(content) as SmartCompactConfig,
    );
    if (!parsed) return null;
    if ((parsed.provider && parsed.model) || parsed.vcc?.enable === true) {
      return parsed;
    }
    return null;
  } catch {
    // Config missing or invalid - extension will be a no-op
    return null;
  }
}

function getPositiveNumber(value: unknown, fallback: number): number {
  return typeof value === "number" && Number.isFinite(value) && value > 0
    ? value
    : fallback;
}

function getRatio(value: unknown, fallback: number): number {
  return typeof value === "number" &&
    Number.isFinite(value) &&
    value > 0 &&
    value <= 1
    ? value
    : fallback;
}

// ctx is a lazy proxy that throws on access once invalidated by session
// replacement/reload, so post-compaction notifications are best-effort.
function notifyStaleSafe(
  ctx: ExtensionContext,
  message: string,
  severity: "info" | "error",
): void {
  try {
    if (ctx.hasUI) ctx.ui.notify(message, severity);
  } catch {
    // Stale ctx; nothing to notify.
  }
}

function getAutoCompactConfig(
  cfg: SmartCompactConfig,
): NormalizedAutoCompactConfig | undefined {
  if (cfg.autoCompact?.enable !== true) {
    return;
  }

  return {
    maxContextTokens: getPositiveNumber(
      cfg.autoCompact.maxContextTokens,
      DEFAULT_AUTO_COMPACT_MAX_CONTEXT_TOKENS,
    ),
    contextRatio: getRatio(
      cfg.autoCompact.contextRatio,
      DEFAULT_AUTO_COMPACT_CONTEXT_RATIO,
    ),
  };
}

function getAutoCompactThreshold(
  contextWindow: number,
  autoConfig: NormalizedAutoCompactConfig,
): number | undefined {
  if (!Number.isFinite(contextWindow) || contextWindow <= 0) {
    return;
  }

  const threshold = Math.min(
    autoConfig.maxContextTokens,
    Math.floor(contextWindow * autoConfig.contextRatio),
  );

  return Number.isFinite(threshold) && threshold > 0 ? threshold : undefined;
}

export default function (pi: ExtensionAPI) {
  let previousTokens: number | null | undefined;
  // Track the effective threshold used for the last crossing check. The
  // threshold is derived from the model's context window and the config
  // ratio/cap, so it can change when the model or config changes. Without
  // tracking it, a lowered threshold leaves previousTokens pinned above the
  // old threshold, so wasBelowOrAtThreshold stays false and compaction never
  // re-fires. Resetting previousTokens when the threshold changes makes the
  // hysteresis re-evaluate from a clean baseline.
  let previousThreshold: number | undefined;
  let autoCompactionInProgress = false;

  // agent_settled fires only after Pi has finished all automatic retries,
  // auto-compaction retries, and queued continuations. Running the threshold
  // check here (instead of agent_end) avoids racing a continuation turn that
  // would otherwise observe a stale, already-compacted context and abort the
  // compaction mid-flight.
  pi.on("agent_settled", async (_event, ctx) => {
    const cfg = await loadCompactionConfig();
    if (!cfg) {
      return;
    }
    const autoCompactConfig = getAutoCompactConfig(cfg);
    if (!autoCompactConfig || autoCompactionInProgress) {
      return;
    }

    // Defensive guard: agent_settled implies idle, but another extension may
    // have started a new run during the async config load above. Bail out
    // rather than compacting into an in-flight turn.
    if (!ctx.isIdle()) {
      return;
    }

    const usage = ctx.getContextUsage();
    if (!usage) {
      return;
    }

    const currentTokens = usage.tokens;
    if (currentTokens === null) {
      return;
    }

    const contextWindow = usage.contextWindow || ctx.model?.contextWindow;
    if (!contextWindow) {
      return;
    }

    const threshold = getAutoCompactThreshold(contextWindow, autoCompactConfig);
    if (!threshold) {
      return;
    }

    // If the effective threshold changed (model or config changed), drop the
    // crossing baseline so hysteresis re-evaluates against the new threshold
    // instead of staying permanently suppressed above the old one.
    if (previousThreshold !== undefined && previousThreshold !== threshold) {
      previousTokens = null;
    }
    previousThreshold = threshold;

    const wasBelowOrAtThreshold =
      previousTokens === undefined ||
      previousTokens === null ||
      previousTokens <= threshold;
    previousTokens = currentTokens;
    if (!wasBelowOrAtThreshold || currentTokens <= threshold) {
      return;
    }

    autoCompactionInProgress = true;
    if (ctx.hasUI) {
      ctx.ui.notify(
        `Auto-compacting ${currentTokens.toLocaleString()} tokens at threshold ${threshold.toLocaleString()}...`,
        "info",
      );
    }

    ctx.compact({
      customInstructions:
        cfg.vcc?.enable === true
          ? "__pi_vcc__"
          : "Auto-compaction triggered because context usage exceeded the configured threshold. Preserve current task state, decisions, modified files, verification results, blockers, and next actions.",
      onComplete: () => {
        autoCompactionInProgress = false;
        previousTokens = null;
        previousThreshold = undefined;
        // State resets must run unconditionally; ctx may be a stale proxy
        // after session replacement/reload, so the notification is best-effort.
        notifyStaleSafe(ctx, "Auto-compaction completed", "info");
      },
      onError: (error) => {
        autoCompactionInProgress = false;
        // Reset hysteresis so a failed or aborted compaction can retry on a
        // subsequent turn. Without this, a failed compaction (e.g. one
        // aborted because a concurrent continuation turn started) leaves
        // previousTokens pointing above threshold, so the crossing
        // detection never re-fires and context is never compacted.
        previousTokens = null;
        previousThreshold = undefined;
        notifyStaleSafe(ctx, `Auto-compaction failed: ${error.message}`, "error");
      },
    });
  });

  pi.on("session_before_compact", async (event, ctx) => {
    const { preparation, signal } = event;
    const cfg = await loadCompactionConfig();
    if (!cfg) return;
    const {
      messagesToSummarize,
      turnPrefixMessages,
      tokensBefore,
      firstKeptEntryId,
      previousSummary,
    } = preparation;

    // If vcc is enabled, let pi-vcc handle the compaction
    if (cfg.vcc?.enable === true) {
      return; // Let pi-vcc's before-compact hook handle it
    }

    // Resolve the configured model
    if (!cfg.provider || !cfg.model) return;
    const model = ctx.modelRegistry.find(cfg.provider, cfg.model);
    if (!model) {
      ctx.ui.notify(
        `Compaction model "${cfg.provider}/${cfg.model}" not found, using default`,
        "warning",
      );
      return;
    }

    // Resolve request auth for the summarization model
    const auth = await ctx.modelRegistry.getApiKeyAndHeaders(model);
    if (!auth.ok) {
      ctx.ui.notify(
        `Compaction auth failed: ${auth.error}, using default compaction`,
        "warning",
      );
      return;
    }
    if (!auth.apiKey) {
      ctx.ui.notify(
        `No API key for ${cfg.provider}, using default compaction`,
        "warning",
      );
      return;
    }

    // Combine all messages for summary
    const allMessages = [...messagesToSummarize, ...turnPrefixMessages];

    ctx.ui.notify(
      `Compacting ${tokensBefore.toLocaleString()} tokens with ${model.id}...`,
      "info",
    );

    // Convert messages to readable text format
    const conversationText = serializeConversation(convertToLlm(allMessages));

    // Include previous summary context if available
    const previousContext = previousSummary
      ? `\n\nPrevious session summary for context:\n${previousSummary}`
      : "";

    // Build messages that ask for a comprehensive summary
    const summaryMessages = [
      {
        role: "user" as const,
        content: [
          {
            type: "text" as const,
            text: `You are a session compaction expert for an AI coding agent. Your goal is to create a "Checkpoint Summary" that enables another agent to resume work with zero loss of technical context.

Include the following in your summary:${previousContext}

### 1. Primary Objective
- Clear statement of the current goal and any background context provided by the user.

### 2. Technical Decisions & Findings
- Key architectural choices or logic implemented.
- Critical findings from codebase research or documentation (e.g., "Library X doesn't support Y").

### 3. Execution History
- **Commands**: List specific shell commands used (e.g., git, nix, npm) and their results if they changed state or provided critical info.
- **Files**: List files modified or created. Be specific about what was changed in each.

### 4. Current Progress & State
- What is finished and verified?
- What is currently being worked on?
- Precise "in-flight" state: Are there open files with unsaved/unverified changes? Is there a failing test?

### 5. Blockers & Open Questions
- Any issues encountered that weren't resolved.
- Things the user needs to clarify.

### 6. Next Actions
- The immediate next 2-3 steps to continue the implementation.

**Constraint**: Be technical, dense, and precise. Prefer code snippets, paths, and exact error messages over vague descriptions. The summary replaces the entire history; if it's not here, it's lost.

Format the summary as structured markdown with clear sections.

<conversation>
${conversationText}
</conversation>`,
          },
        ],
        timestamp: Date.now(),
      },
    ];

    try {
      // Pass signal to honor abort requests
      const response = await complete(
        model,
        { messages: summaryMessages },
        {
          apiKey: auth.apiKey,
          headers: auth.headers,
          maxTokens: cfg.maxTokens ?? model.maxTokens,
          signal,
        },
      );

      const summary = response.content
        .filter((c): c is { type: "text"; text: string } => c.type === "text")
        .map((c) => c.text)
        .join("\n");

      if (!summary.trim()) {
        if (!signal.aborted) {
          ctx.ui.notify(
            "Compaction summary was empty, using default",
            "warning",
          );
        }
        return;
      }

      // Return compaction content
      return {
        compaction: {
          summary,
          firstKeptEntryId,
          tokensBefore,
        },
      };
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      ctx.ui.notify(`Compaction failed: ${message}, using default`, "error");

      // Fall back to default compaction on error
      return;
    }
  });
}
